<script src="<?php echo esc_url(plugins_url('assets/js/html2pdf.bundle.min.js', dirname(__FILE__))); ?>"></script>
<script>
function downloadAsPdf() {
  const element = document.querySelector('.invoice');
  const btn = document.getElementById('downloadPdfBtn');
  if (btn) btn.innerHTML = '⏳ Generating PDF...';
  const opt = {
    margin: [4, 4, 4, 4],
    filename: 'Dior-Medical-Invoice-' + <?php echo json_encode(preg_replace('/[^a-zA-Z0-9_-]/', '', $invoice_id)); ?> + '.pdf',
    image: { type: 'jpeg', quality: 0.98 },
    html2canvas: { scale: 2, useCORS: true, logging: false },
    jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
  };
  return html2pdf().set(opt).from(element).save().then(function() {
    if (btn) btn.innerHTML = 'Download PDF';
  }).catch(function(err) {
    if (btn) btn.innerHTML = 'Download PDF';
    console.error('Invoice PDF error:', err);
  });
}

window.addEventListener('DOMContentLoaded', function() {
  var urlParams = new URLSearchParams(window.location.search);
  if (urlParams.get('download') === '1') {
    setTimeout(downloadAsPdf, 800);
  }
});
</script>
